// 1. USE: Passes to next middleware
app.Use(async (context, next) => {
    Console.WriteLine("Before");
    await next();  // continue pipeline
});

// 2. MAP: Branches the pipeline based on URL
app.Map("/health", branch => {
    // 3. RUN: Terminal! Stops the pipeline and returns a response.
    branch.Run(async ctx => await ctx.Response.WriteAsync("API is Healthy!"));
});

var app = builder.Build();

app.UseHttpsRedirection();

// 1. Figure out which endpoint they want
app.UseRouting();          

// 2. Parse their JWT token to figure out WHO they are
app.UseAuthentication();   

// 3. Check if they are ALLOWED to access the endpoint
app.UseAuthorization();    

// 4. Actually run the code!
app.MapControllers();
